// Scrape only the FCI IDs missing from fci-full-raw.json
// Reads fci-gap-ids.json (generated by find-gaps.mjs), scrapes each ID,
// appends found judges to fci-full-raw.json.
//
// Run: node scrape-fci-gaps.js
// Supports resume: already-found IDs are skipped on restart.

import puppeteer from "puppeteer";
import fs from "fs";
import { FCI_GROUP_NAMES, FCI_GROUP_BREEDS } from "./fci-groups.js";

const DELAY_MS     = 1000;
const RESTART_EVERY = 300;
const SAVE_EVERY   = 50;
const OUTPUT       = "fci-full-raw.json";
const GAP_FILE     = "fci-gap-ids.json";
const PROGRESS_FILE= "fci-gaps-progress.json";

// ── Reuse helpers from main scraper ──────────────────────────────────────────
const FLAGS = {
  "AFGHANISTAN":"🇦🇫","ALBANIA":"🇦🇱","ALGERIA":"🇩🇿","ANDORRA":"🇦🇩","ARGENTINA":"🇦🇷",
  "ARMENIA":"🇦🇲","AUSTRALIA":"🇦🇺","AUSTRIA":"🇦🇹","AZERBAIJAN":"🇦🇿","BAHRAIN":"🇧🇭",
  "BELARUS":"🇧🇾","BELGIUM":"🇧🇪","BOLIVIA":"🇧🇴","BOSNIA AND HERZEGOVINA":"🇧🇦","BRAZIL":"🇧🇷",
  "BULGARIA":"🇧🇬","CANADA":"🇨🇦","CHILE":"🇨🇱","CHINA":"🇨🇳","CHINA (PEOPLE'S REPUBLIC OF)":"🇨🇳",
  "COLOMBIA":"🇨🇴","COSTA RICA":"🇨🇷","CROATIA":"🇭🇷","CUBA":"🇨🇺","CYPRUS":"🇨🇾",
  "CZECH REPUBLIC":"🇨🇿","DENMARK":"🇩🇰","DOMINICAN REPUBLIC":"🇩🇴","ECUADOR":"🇪🇨",
  "EGYPT":"🇪🇬","ESPAÑA":"🇪🇸","ESTONIA":"🇪🇪","FINLAND":"🇫🇮","FRANCE":"🇫🇷",
  "GEORGIA":"🇬🇪","GERMANY":"🇩🇪","GREECE":"🇬🇷","GUATEMALA":"🇬🇹","HONG KONG":"🇭🇰",
  "HUNGARY":"🇭🇺","ICELAND":"🇮🇸","INDIA":"🇮🇳","INDONESIA":"🇮🇩","IRAN":"🇮🇷",
  "IRELAND":"🇮🇪","ISRAEL":"🇮🇱","ITALY":"🇮🇹","JAPAN":"🇯🇵","KAZAKHSTAN":"🇰🇿",
  "KENYA":"🇰🇪","KOREA (REPUBLIC OF)":"🇰🇷","SOUTH KOREA":"🇰🇷","KUWAIT":"🇰🇼",
  "LATVIA":"🇱🇻","LIECHTENSTEIN":"🇱🇮","LITHUANIA":"🇱🇹","LUXEMBOURG":"🇱🇺",
  "MALAYSIA":"🇲🇾","MALTA":"🇲🇹","MEXICO":"🇲🇽","MOLDOVA":"🇲🇩","MONACO":"🇲🇨",
  "MONTENEGRO":"🇲🇪","MOROCCO":"🇲🇦","NETHERLANDS":"🇳🇱","NEW ZEALAND":"🇳🇿",
  "NIGERIA":"🇳🇬","NORTH MACEDONIA":"🇲🇰","NORWAY":"🇳🇴","PANAMA":"🇵🇦",
  "PARAGUAY":"🇵🇾","PERU":"🇵🇪","PHILIPPINES":"🇵🇭","POLAND":"🇵🇱","PORTUGAL":"🇵🇹",
  "PUERTO RICO":"🇵🇷","QATAR":"🇶🇦","ROMANIA":"🇷🇴","RUSSIA":"🇷🇺","SAN MARINO":"🇸🇲",
  "SAUDI ARABIA":"🇸🇦","SERBIA":"🇷🇸","SINGAPORE":"🇸🇬","SLOVAKIA":"🇸🇰",
  "SLOVENIA":"🇸🇮","SOUTH AFRICA":"🇿🇦","SPAIN":"🇪🇸","SWEDEN":"🇸🇪","SWITZERLAND":"🇨🇭",
  "TAIWAN":"🇹🇼","THAILAND":"🇹🇭","TUNISIA":"🇹🇳","TURKEY":"🇹🇷","UKRAINE":"🇺🇦",
  "UNITED ARAB EMIRATES":"🇦🇪","UAE":"🇦🇪","UNITED KINGDOM":"🇬🇧","UK":"🇬🇧",
  "UNITED STATES":"🇺🇸","USA":"🇺🇸","URUGUAY":"🇺🇾","VENEZUELA":"🇻🇪","VIETNAM":"🇻🇳",
};
const DISCIPLINE_GROUPS = {
  "Shows":"A","British Pointers":"B","Continental and British Pointers":"B",
  "Continental Pointers":"B","Retrievers":"B","Spaniels":"B","Nordic Hunting Dogs":"B",
  "Hounds of the 6th Group":"B","Earth Dogs":"B","Water Work":"B",
  "Obedience":"C","Rally Obedience":"C","Utility Dogs":"C","Mondioring":"C",
  "Agility":"D","Hoopers":"D","Flyball":"D","Sighthound Lure Coursing":"D",
  "Sighthound Race":"D","Canicross & Turnierhundsport":"D",
  "Natural truffle search":"E","Square truffle search":"E","Truffle search (Work)":"E",
  "Herding Dogs":"F","Rescue Dogs":"F","Sledge Dogs":"F",
  "Grooming":"G","Dog Dancing":"H",
};
const LOWERCASE_PARTICLES = new Set(["de","van","von","del","der","la","le","di","da","dos","das"]);
function toTitleCase(str) {
  if (!str) return "";
  return str.trim().split(/\s+/).map(w => {
    const l = w.toLowerCase();
    if (LOWERCASE_PARTICLES.has(l)) return l;
    return w.split("-").map(part => {
      const pl = part.toLowerCase();
      if (LOWERCASE_PARTICLES.has(pl)) return pl;
      return part.charAt(0).toUpperCase() + part.slice(1).toLowerCase();
    }).join("-");
  }).join(" ");
}
function parseDate(str) {
  if (!str) return null;
  const m = str.trim().match(/^(\d{2})-(\d{2})-(\d{4})$/);
  return m ? `${m[3]}-${m[2]}-${m[1]}` : null;
}
function toSlug(name) {
  return name.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"")
    .replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
}
function sleep(ms) { return new Promise(r=>setTimeout(r,ms)); }
function jitter(base=1000, spread=600) { return base + Math.random()*spread; }

let browser, page;

async function dismissPopup() {
  try {
    const clicked = await page.evaluate(() => {
      const btn = Array.from(document.querySelectorAll("button,a"))
        .find(x => x.innerText?.trim() === "Close");
      if (btn) { btn.click(); return true; }
      return false;
    });
    if (clicked) await sleep(800);
  } catch(e) {}
}

async function initBrowser(label="") {
  if (browser) { try { await browser.close(); } catch(e) {} browser=null; page=null; }
  browser = await puppeteer.launch({
    headless:true,
    args:["--no-sandbox","--disable-setuid-sandbox","--disable-dev-shm-usage"],
    defaultViewport:{width:1280,height:900},
  });
  page = await browser.newPage();
  await page.setUserAgent("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36");
  try {
    await page.goto("https://www.fci.be/en/judges",{waitUntil:"networkidle2",timeout:20000});
    await sleep(1500);
    await dismissPopup();
    console.log(`✅ Browser ready${label?" ("+label+")":""}`);
  } catch(e) { console.log(`⚠️  Prime failed: ${e.message}`); }
}

async function scrapeJudge(id, attempt=1) {
  try {
    const resp = await page.goto(`https://www.fci.be/en/judges/Judge.aspx?id=${id}`,
      {waitUntil:"networkidle2",timeout:25000});
    if (!resp || resp.status()===404) return null;
    await dismissPopup();

    const data = await page.evaluate((FLAGS, DISCIPLINE_GROUPS, FCI_GROUP_BREEDS) => {
      const h3pink = document.querySelector("h3.pink");
      if (!h3pink) return null;
      const rawName = h3pink.innerText.trim();
      if (!rawName) return null;
      const badName = rawName.length < 3 || /^[\s.,\-_0-9]+$/.test(rawName) || (rawName.match(/[a-zA-ZÀ-žА-я]/g)||[]).length < 2;

      let birthYear=null;
      for (const col of document.querySelectorAll(".col-md-11.vcenter")) {
        const txt=col.innerText.trim();
        if (/^\d{4}$/.test(txt)){birthYear=parseInt(txt);break;}
      }

      let kennelClub="",kennelClubCountry="",countryOfResidence="";
      for (const row of document.querySelectorAll(".row .row")) {
        const h3=row.querySelector("h3"), val=row.querySelector(".col-md-6:last-child");
        if(!h3||!val) continue;
        const label=h3.innerText.trim(), value=val.innerText.trim();
        if(label.includes("National Canine")){
          const m=value.match(/^(.+?)\s*\(([^)]+)\)\s*$/);
          if(m){kennelClub=m[1].trim();kennelClubCountry=m[2].trim();}
          else kennelClub=value;
        }
        if(label.includes("Country of legal")) countryOfResidence=value;
      }

      let fciLicenceId=null,fciLicenceCountry=null,fciLicenceNumber=null,fciLicenceDate=null;
      const licRows=document.querySelectorAll(".table-responsive table tr");
      for(const tr of licRows){
        const cells=Array.from(tr.querySelectorAll("td")).map(td=>td.innerText.trim());
        if(cells.length>=2&&/^[A-Z]{2}\d+$/.test(cells[0])){
          fciLicenceId=cells[0];
          const m=cells[0].match(/^([A-Z]{2})(\d+)$/);
          if(m){fciLicenceCountry=m[1];fciLicenceNumber=parseInt(m[2]);}
          if(cells[1]) fciLicenceDate=cells[1];
          break;
        }
      }

      let flag="",country="";
      for(const img of document.querySelectorAll("img")){
        const src=img.src||""; const alt=(img.alt||"").toUpperCase().trim();
        if(src.includes("/flag")&&alt){
          country=alt;
          const f=Object.entries(FLAGS).find(([k])=>k===alt||alt.includes(k)||k.includes(alt));
          if(f) flag=f[1];
          break;
        }
      }
      if(!country&&kennelClubCountry) country=kennelClubCountry;

      const disciplines=[],disciplineGroups=new Set();
      const allBreedSections=[];
      let allBreedJudge=false;
      const groupNames=[];

      for(const section of document.querySelectorAll(".panel,.card,[class*='panel']")){
        const header=section.querySelector("h3,h4,.panel-title,.card-title");
        if(!header) continue;
        const headerText=header.innerText.trim();
        const group=DISCIPLINE_GROUPS[headerText]||null;
        if(group) disciplineGroups.add(group);

        const breedList=[];
        for(const li of section.querySelectorAll("li")){
          const t=li.innerText.trim();
          if(t&&t.length>1&&t!==headerText) breedList.push(t);
        }

        if(headerText==="Shows"||group==="A"){
          const isAllBreed=section.innerText.includes("All breeds")||
            section.innerText.includes("all breeds");
          if(isAllBreed){
            allBreedJudge=true;
          } else {
            for(const li of section.querySelectorAll("li")){
              const t=li.innerText.trim();
              if(t&&t.length>1) allBreedSections.push(t);
            }
          }
          const fciGroups=[...section.querySelectorAll(".col-md-6 ul")]
            .flatMap(ul=>[...ul.querySelectorAll("li")].map(li=>li.innerText.trim()))
            .filter(Boolean);
          if(fciGroups.length) groupNames.push(...fciGroups);
        }

        if(breedList.length&&group&&group!=="A") disciplines.push(headerText);
      }

      const authorizedBreeds=allBreedSections.filter(Boolean);
      const fciLanguages=[];
      for(const row of document.querySelectorAll(".row .row")){
        const h3=row.querySelector("h3"),val=row.querySelector(".col-md-6:last-child");
        if(!h3||!val) continue;
        if(h3.innerText.includes("Languages")){
          fciLanguages.push(...val.innerText.split(",").map(s=>s.trim()).filter(Boolean));
          break;
        }
      }

      // Email — from mailto links (most reliable, avoids false "(private)" exclusion)
      let email = null;
      const mailtoLinks = Array.from(document.querySelectorAll('a[href^="mailto:"]'));
      if(mailtoLinks.length>0){
        email = mailtoLinks[0].href.replace('mailto:','').trim().split('?')[0];
      } else {
        const bodyText = document.body.innerText;
        const emailMatch = bodyText.match(/[\w.+-]+@[\w.-]+\.[a-z]{2,}/i);
        if(emailMatch) email = emailMatch[0];
      }

      return {
        rawName,badName,birthYear,kennelClub,kennelClubCountry,countryOfResidence,
        fciLicenceId,fciLicenceCountry,fciLicenceNumber,fciLicenceDate,
        flag,country,email,
        disciplines,disciplineGroups:[...disciplineGroups],
        allBreedJudge,authorizedBreeds,groupNames,fciLanguages,
      };
    }, FLAGS, DISCIPLINE_GROUPS, FCI_GROUP_BREEDS);

    if (!data) return null;

    const name = toTitleCase(data.rawName);
    const slug = toSlug(name);
    return {
      id:`fci_${id}`,fciUrlId:id,
      fciLicenceId:data.fciLicenceId,fciLicenceCountry:data.fciLicenceCountry,
      fciLicenceNumber:data.fciLicenceNumber,fciLicenceDate:parseDate(data.fciLicenceDate),
      name,slug,slugAliases:[],
      photo:name.split(" ").map(w=>w[0]).filter(Boolean).slice(0,2).join("").toUpperCase()||"??",
      country:toTitleCase(data.country||data.kennelClubCountry||""),
      flag:FLAGS[(data.country||"").toUpperCase()]||data.flag||"",
      kennelClub:data.kennelClub,kennelClubCountry:data.kennelClubCountry,
      countryOfResidence:data.countryOfResidence,
      birthYear:data.birthYear,licensedYear:null,licensedDate:null,
      orgs:[{org:"FCI",id:data.fciLicenceId||`FCI-${id}`}],
      disciplines:data.disciplines,disciplineGroups:data.disciplineGroups.length?data.disciplineGroups:["A"],
      allBreedJudge:data.allBreedJudge,
      groupNames:data.groupNames.map(g=>({group:g,name:FCI_GROUP_NAMES[g]||g})),
      authorizedBreeds:data.authorizedBreeds,breeds:data.authorizedBreeds,
      fciLanguages:data.fciLanguages,otherLanguages:[],
      suspensions:[],contact:{email:data.email||null,phone:null,address:null},
      kennelName:null,bisJudge:false,
      verified:false,claimedBy:null,bio:"",social:{},highlights:[],headline:"",
      source:"FCI",status:"active",
      hidden: data.badName ? true : false,
      scrapedAt:new Date().toISOString(),lastUpdated:new Date().toISOString(),
    };
  } catch(e) {
    // Retry up to 2 more times on timeout/network errors
    if (attempt < 3 && (e.message.includes("timeout") || e.message.includes("net::"))) {
      await sleep(jitter(2000, 1000));
      return scrapeJudge(id, attempt + 1);
    }
    return null;
  }
}

// ── Main ──────────────────────────────────────────────────────────────────────
const gapIds = JSON.parse(fs.readFileSync(GAP_FILE,"utf8"));

// Load existing data
const existing = JSON.parse(fs.readFileSync(OUTPUT,"utf8"));
const haveIds  = new Set(existing.judges.map(j=>parseInt(j.id.replace("fci_",""))));

// Load progress (which gaps we've already attempted)
let attempted = new Set();
if (fs.existsSync(PROGRESS_FILE)) {
  const p = JSON.parse(fs.readFileSync(PROGRESS_FILE,"utf8"));
  attempted = new Set(p.attempted||[]);
}

const toScrape = gapIds.filter(id => !haveIds.has(id) && !attempted.has(id));
console.log(`🔍 Gap IDs to probe: ${gapIds.length} total, ${toScrape.length} not yet attempted`);

await initBrowser("start");

const newJudges = [];
let done = 0;

for (let i=0; i<toScrape.length; i++) {
  const id = toScrape[i];

  if (i>0 && i%RESTART_EVERY===0) {
    await initBrowser(`restart at ${id}`);
  }

  const judge = await scrapeJudge(id);
  attempted.add(id);

  if (judge) {
    newJudges.push(judge);
    console.log(`✅ [${id}] ${judge.name} | ${judge.country} | total new: ${newJudges.length}`);
  }

  done++;

  if (done%SAVE_EVERY===0 || i===toScrape.length-1) {
    // Read fresh from disk each time to avoid stale base data causing duplicates.
    // Only append judges not already in the file.
    const onDisk = JSON.parse(fs.readFileSync(OUTPUT,"utf8"));
    const onDiskIds = new Set(onDisk.judges.map(j=>j.id));
    const trulyNew = newJudges.filter(j => !onDiskIds.has(j.id));
    const merged = [...onDisk.judges, ...trulyNew];
    merged.sort((a,b)=>{
      const na=parseInt(a.id.replace(/\D/g,""))||0, nb=parseInt(b.id.replace(/\D/g,""))||0;
      return na-nb;
    });
    merged[0] && (merged[0].count = merged.length); // unused, just use the object directly
    fs.writeFileSync(OUTPUT, JSON.stringify({count:merged.length,scrapedAt:new Date().toISOString(),judges:merged},null,2));
    fs.writeFileSync(PROGRESS_FILE, JSON.stringify({
      attempted:[...attempted], done, found:newJudges.length,
      savedAt:new Date().toISOString(),
    }));
    console.log(`💾 Saved — probed ${done}/${toScrape.length}, found ${newJudges.length} new judges`);
  }

  await sleep(jitter(DELAY_MS, 500));
}

await browser.close();
console.log(`\n🎉 Done! Found ${newJudges.length} new judges from ${toScrape.length} gap IDs`);
console.log(`Total judges in ${OUTPUT}: ${existing.count}`);
